def first_repeat_index(values):
    seen = set()
    for index, value in enumerate(values):
        if value in seen:
            return index
        seen.add(value)
    return -1

def word_lengths(text):
    words = text.split()
    return [len(word) for word in words]

def collapse_hyphens(text):
    result = []
    current_run = []
    for char in text:
        if char == '-':
            current_run.append(char)
        else:
            if current_run:
                result.append('-')
            result.append(char)
