def parenthesis_balance(text):
    balance = 0
    for char in text:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def transpose_rect(matrix):
    if not matrix:
        return []
    # Check for ragged rows
    for row in matrix:
        if len(row) != len(matrix[0]):
            raise ValueError("Ragged rows are not allowed.")
    # Transpose the matrix
    transposed = [[matrix[j][i] for j in range(len(matrix))] for i in range(len(matrix[0]))]
    return transposed

