def middle_item(values):
    if not values:
        raise ValueError('Sequence is empty')
    if len(values) % 2 == 0:
        raise ValueError('Sequence length is even')
    return values[len(values) // 2]

def running_max(values):
    if not values:
        return []
    max_so_far = values[0]
    result = [max_so_far]
    for value in values[1:]:
        if value > max_so_far:
            max_so_far = value
        result.append(max_so_far)
    return result

